"""Deterministic stand-in for the engine installer / version-reporting surface.

Only the operations the client actually uses are modelled:
    available_version(source) -> Version | None   (probe; installs nothing)
    installed_version()      -> Version | None   (what the engine declares)
    install(source, version) -> None
plus ensure(source, minimum) -> (Version, changed) with the reconciliation
rules from the specification. No network, no clock, no ambient state.
"""
from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Iterable, Optional, Tuple

_SEMVER = re.compile(r"^(\d+)\.(\d+)\.(\d+)$")


class EngineError(RuntimeError):
    """Base error for the engine surface."""


class EngineUnavailableError(EngineError):
    """The configured source offers no engine and none is installed."""


class EngineInstallError(EngineError):
    """The installer refused or failed to install a version."""


class MinimumNotSatisfiedError(EngineError):
    """The resulting engine is below the declared minimum."""


@dataclass(frozen=True, order=True)
class Version:
    major: int
    minor: int
    patch: int

    @classmethod
    def parse(cls, text: object) -> "Version":
        if isinstance(text, Version):
            return text
        match = _SEMVER.match(str(text).strip())
        if match is None:
            raise ValueError("not a version: %r" % (text,))
        return cls(*(int(part) for part in match.groups()))

    def __str__(self) -> str:
        return "%d.%d.%d" % (self.major, self.minor, self.patch)


class FakeEngine:
    """In-memory engine whose state is fully controlled by the test."""

    def __init__(self, channel, installed: Optional[Version] = None,
                 broken: Iterable[Version] = (), unavailable_sources=()):
        self._channel = channel
        self._installed = None if installed is None else Version.parse(installed)
        self._broken = {Version.parse(v) for v in broken}
        self._unavailable = set(unavailable_sources)
        self.install_calls = []

    # probe: must never mutate anything
    def available_version(self, source: str) -> Optional[Version]:
        if source in self._unavailable:
            return None
        return self._channel.latest(source)

    # what the installed engine itself declares
    def installed_version(self) -> Optional[Version]:
        return self._installed

    def install(self, source: str, version: Version) -> None:
        version = Version.parse(version)
        self.install_calls.append((source, version))
        if version in self._broken:
            raise EngineInstallError(
                "engine installer rejected %s from source %r"
                % (version, source))
        artifact = self._channel.fetch(source, version)
        self._installed = artifact.version

    def ensure(self, source: str, minimum: Version) -> Tuple[Version, bool]:
        """Reconcile installed vs available; return (version, changed)."""
        minimum = Version.parse(minimum)
        available = self.available_version(source)
        current = self.installed_version()
        changed = False

        if available is None:
            if current is None:
                raise EngineUnavailableError(
                    "no engine is installed and the configured engine source "
                    "%r offers none; point 'engine_source' at a reachable "
                    "engine location or install an engine of at least %s"
                    % (source, minimum))
        elif current is None or available > current:
            self.install(source, available)
            changed = True
        # current >= available: kept untouched, no install call

        installed = self.installed_version()
        if installed is None or installed < minimum:
            raise MinimumNotSatisfiedError(
                "installed engine %s is below the required minimum %s; "
                "make a source that provides at least %s available as the "
                "configured engine source"
                % (installed, minimum, minimum))
        return installed, changed

"""Deterministic in-memory engine distribution channel.

One instance stands in for the configured engine source. It answers the two
questions the installer seam asks: which versions does a source publish, and
give me the artifact for an exact version. Nothing is fetched over a network.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable, Mapping, Optional

from .engine import Version  # semver type defined with the engine stub


class ChannelError(RuntimeError):
    """The source has no such artifact."""


@dataclass(frozen=True)
class Artifact:
    version: Version
    location: str


class FakeEngineChannel:
    """Catalogue of engine artifacts keyed by configured source string."""

    def __init__(self, catalogue: Optional[Mapping[str, Iterable[object]]] = None):
        self._catalogue = {}
        for source, versions in (catalogue or {}).items():
            for version in versions:
                self.publish(source, version)

    def publish(self, source: str, version: object) -> None:
        parsed = Version.parse(version)
        location = "mem://%s/engine-%s" % (source, parsed)
        self._catalogue.setdefault(source, {})[parsed] = Artifact(parsed, location)

    def versions(self, source: str):
        return sorted(self._catalogue.get(source, {}))

    def latest(self, source: str) -> Optional[Version]:
        available = self.versions(source)
        return available[-1] if available else None

    def fetch(self, source: str, version: object) -> Artifact:
        parsed = Version.parse(version)
        try:
            return self._catalogue[source][parsed]
        except KeyError:
            raise ChannelError(
                "source %r publishes no engine %s (available: %s)"
                % (source, parsed,
                   ", ".join(str(v) for v in self.versions(source)) or "none"))
